    public static bool TryGet(string recipeId, out int ability, out float levelMultiplier)
    {
        if (recipeId != null && Required.TryGetValue(recipeId, out (int Ability, float LevelMultiplier) req))
        {
            ability = req.Ability;
            levelMultiplier = req.LevelMultiplier;
            return true;
        }
        ability = 0;
        levelMultiplier = 0f;
        return false;
    }
}

