    public static bool TryGet(string blueprintId, out int ability, out float levelMultiplier)
    {
        if (blueprintId != null && Required.TryGetValue(blueprintId, out (int Ability, float LevelMultiplier) req))
        {
            ability = req.Ability;
            levelMultiplier = req.LevelMultiplier;
            return true;
        }
        ability = 0;
        levelMultiplier = 0f;
        return false;
    }
